'<body>' +
'<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;"><a href="/webhook/aktien-status" style="color:#8ab4f8;text-decoration:none;">Status</a><a href="/webhook/aktien-watchlist" style="color:#8ab4f8;text-decoration:none;">Watchlist</a><a href="/webhook/rss-quellen" style="color:#8ab4f8;text-decoration:none;">RSS-Quellen</a><a href="/webhook/lernvorschlaege" style="color:#8ab4f8;text-decoration:none;">Lernvorschlaege</a><a href="/webhook/historische-marktdaten" style="color:#8ab4f8;text-decoration:none;">Marktdaten-Import</a><a href="/webhook/historische-nachrichten" style="color:#8ab4f8;text-decoration:none;">Nachrichten-Import</a><a href="/webhook/historische-news-lernkandidaten" style="color:#8ab4f8;text-decoration:none;">News-Lernkandidaten</a><a href="/webhook/historische-news-ausschluesse" style="color:#8ab4f8;text-decoration:none;">Ausschlussregeln</a><a href="/webhook/historische-simulation" style="color:#8ab4f8;text-decoration:none;">Simulationslaeufe</a><a href="/webhook/simulation-lauf" style="color:#8ab4f8;text-decoration:none;">Simulation starten</a><a href="/webhook/simulation-uebersicht" style="color:#8ab4f8;text-decoration:none;">Sim-Uebersicht</a><a href="/webhook/simulation-vergleich" style="color:#8ab4f8;text-decoration:none;">Sim-Vergleich</a></div>' +
