'  <div class="hint">Vorschlaege aus 09 (Lernagent Newswirkung, Samstag 08:00). "Freigeben &amp; aktivieren" schreibt den neuen Gewichtswert sofort produktiv nach trading.scoring_weights (vorherige aktive Version wird deaktiviert, nicht geloescht) und markiert den Vorschlag als aktiviert.</div>' +
'  <table>' +
'    <thead><tr><th>ID</th><th>Ziel</th><th>Aktuell \u2192 Vorschlag</th><th>Fallzahl</th><th>Konfidenz</th><th>Begruendung</th><th>Status</th><th>Aktion</th></tr></thead>' +
'    <tbody>' + rowsHtml + '</tbody>' +
'  </table>' +
'</body>' +
'</html>';

return [{ json: { html } }];

function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v); }

// FIX 2026-08-01 (Fehleranalyse A5): ab hier vertraut der Workflow dem Browser nur noch fuer
// id/action/reviewer/reason. Alle inhaltlichen Vorschlagsfelder (proposal_type/target_type/
// target_value/proposed_value/time_horizon) werden im naechsten Schritt frisch aus der DB
// geladen, nie aus dem POST-Body uebernommen - jedes versteckte Formularfeld mit einem
// abweichenden Wert wird dadurch wirkungslos.
const j = $json.body || $json;
const action = String(j.action || '').trim();
const id = pgNum(j.id);
const reviewer = String(j.reviewer || '').trim() || 'unbekannt';
const reason = String(j.reason || '').trim();
// FIX 2026-08-02 (Fehleranalyse A10): submittedVersion ist wie reviewer/reason
// ein zulaessiger Browser-Wert - kein Inhaltsfeld, sondern ein reines
// Konkurrenz-Token (Optimistic Locking), gegen den frisch geladenen
// DB-Wert geprueft in "POST: Formular normalisieren + SQL bauen".
const submittedVersion = pgNum(j.version);

return {
  json: {
    action,
    reviewer,
    reason,
    id,
    submittedVersion,
    load_sql: id !== null
      ? `SELECT id, proposal_type, target_type, target_value, proposed_value, time_horizon, status, version
         FROM trading.learning_rule_proposals WHERE id = ${id};`
      : `SELECT NULL::bigint AS id WHERE FALSE;`
  }
};

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v); }

// FIX 2026-08-01 (Fehleranalyse A5): proposal_type/target_type/target_value/proposed_value/
// time_horizon kommen ab hier ausschliesslich aus der frisch geladenen DB-Zeile (voriger Node
// "DB: Proposal laden (fuer Freigabe)"), nie aus dem POST-Body - siehe "POST: Baue Load-Query".
const loaded = $json;
const ctx = $('POST: Baue Load-Query').item.json;
const action = ctx.action;
const reviewer = ctx.reviewer;
const id = (loaded && loaded.id !== undefined && loaded.id !== null) ? Number(loaded.id) : null;

// FIX 2026-08-02 (Fehleranalyse A10, mittel): Optimistic Locking ueber das
// bereits vorhandene, aber nie genutzte version-Feld. submittedVersion kommt
// aus dem versteckten Formularfeld (beim Laden der Liste eingebettet) und
// wird NUR als Konkurrenz-Token verglichen, nicht als Inhaltsquelle (A5
// bleibt vollstaendig in Kraft - die eigentlichen Werte kommen weiterhin aus
// "loaded", nie aus ctx/dem Body). Hat sich der Vorschlag seit dem Laden der
// Seite bereits geaendert (jemand anderes hat ihn zwischenzeitlich bearbeitet,
// version wurde dabei hochgezaehlt), greift dieselbe "kein passender Vorschlag"-
// Behandlung wie bei einem falschen Status.
const submittedVersion = ctx.submittedVersion;
const versionMismatch = submittedVersion !== null && submittedVersion !== undefined
  && loaded && loaded.version !== undefined && Number(submittedVersion) !== Number(loaded.version);

// FIX 2026-08-01 (Fehleranalyse A8, hoch; loest gleichzeitig A7 vollstaendig ab): zentrale
// Regeltabelle (Datentyp/Min/Max/NULL-Policy) je Vorschlagstyp, serverseitig durchgesetzt vor
// jedem Ziel-Update. Ersetzt die bisherige Einzel-Allowlist fuer threshold_adjustment (A7,
// teilweise) durch eine einheitliche Struktur, die auch fuer strategy_parameter_change und
// regime_restriction gilt. Die Wertebereiche fuer strategy_parameter_change stammen aus den
// tatsaechlichen Default-Seed-Werten in sql/036 (stop_atr_multiplier/target_atr_multiplier/
// horizon_days sind die einzigen drei dort verwendeten Schluessel je Strategie - vollstaendig
// enumerierbar, kein Freitext). fit_multiplier-Grenzen aus dem Tabellenkommentar von
// strategy_regime_matrix (sql/032: "0=vollstaendig blockiert, 1=volle Eignung"). weight_value-
// Grenzen uebernommen aus der bereits bestehenden, getesteten Validierung in Workflow 09 (F2-
// Fix, MIN_WEIGHT/MAX_WEIGHT). Bewusst NICHT umgesetzt: eine maximale Schrittweite gegenueber
// dem aktuellen Live-Wert (wuerde eine zusaetzliche Vorab-Query je Ziel erfordern) - die
// absoluten Grenzen unten schliessen aber bereits das im Fund konkret genannte Beispiel
// (MAX_RISK_PER_TRADE_PCT auf 99%) zuverlaessig aus.
const RULE_TABLE = {
  threshold_adjustment: {
    MIN_REWARD_RISK_RATIO:        { min: 0.5, max: 10,  allowNull: false },
    MAX_RISK_PER_TRADE_PCT:       { min: 0.1, max: 10,  allowNull: false },
    MAX_POSITION_VALUE_PCT:       { min: 1,   max: 100, allowNull: false },
    MAX_OPEN_POSITIONS:           { min: 1,   max: 50,  allowNull: false, integer: true },
    MAX_SECTOR_EXPOSURE_PCT:      { min: 1,   max: 100, allowNull: false },
    MAX_DIRECTIONAL_EXPOSURE_PCT: { min: 1,   max: 100, allowNull: false },
    MAX_PORTFOLIO_DRAWDOWN_PCT:   { min: 1,   max: 100, allowNull: false },
    DRY_RUN:                      { min: 0,   max: 1,   allowNull: false, integer: true },
    REQUIRE_CONFIRMATION:         { min: 0,   max: 1,   allowNull: false, integer: true }
  },
  strategy_parameter_change: {
    stop_atr_multiplier:   { min: 0.3, max: 5,  allowNull: false },
    target_atr_multiplier: { min: 0.5, max: 10, allowNull: false },
    horizon_days:           { min: 1,  max: 60, allowNull: false, integer: true }
  }
};
const FIT_MULTIPLIER_RULE = { min: 0, max: 1, allowNull: false };
const WEIGHT_VALUE_RULE = { min: 0.1, max: 3.0, allowNull: false };
const VALID_STRATEGIES = new Set(['mean_reversion', 'trend_following', 'breakout', 'news_event']);
const VALID_COMBINED_REGIMES = new Set(['bull_trend_low_vol', 'bull_trend_high_vol', 'sideways_low_vol', 'sideways_high_vol', 'bear_trend', 'stress', 'unknown']);

function checkRule(rule, value) {
  if (value === null) return rule.allowNull ? { ok: true } : { ok: false, reason: 'Wert fehlt/nicht numerisch' };
  if (rule.integer && !Number.isInteger(value)) return { ok: false, reason: 'Wert muss ganzzahlig sein' };
  if (value < rule.min || value > rule.max) return { ok: false, reason: `Wert ${value} ausserhalb des zulaessigen Bereichs [${rule.min}, ${rule.max}]` };
  return { ok: true };
}

let sql;

if (id === null || loaded.status !== 'proposed' || versionMismatch) {
  // Kein passender, noch offener Vorschlag gefunden (oder er wurde
  // zwischenzeitlich veraendert, siehe versionMismatch oben) - egal was
  // action/id im Body behaupten.
  sql = 'SELECT 1;';
} else if (action === 'reject') {
  sql = `UPDATE trading.learning_rule_proposals
    SET status = 'rejected', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1
    WHERE id = ${id} AND status = 'proposed';`;
} else if (action === 'approve') {
  const proposalType = String(loaded.proposal_type || 'weight_adjustment').trim();
  const targetType = String(loaded.target_type || '').trim();
  const targetValue = String(loaded.target_value || '').trim();
  const timeHorizon = String(loaded.time_horizon || '').trim();
  // Live-Guard gegen konkurrierende Freigaben derselben id zwischen Laden und Schreiben
  // (Fehleranalyse A10, teilweise): das Ziel-Update greift nur, wenn der Vorschlag zum
  // tatsaechlichen Ausfuehrungszeitpunkt noch 'proposed' ist.
  const eligible = `EXISTS (SELECT 1 FROM trading.learning_rule_proposals WHERE id = ${id} AND status = 'proposed')`;

  const proposedValue = pgNum(loaded.proposed_value);

  // Zentrale Pruefung: Zielobjekt (Allowlist) + Wertebereich, je Vorschlagstyp.
  let validationFailed = false;
  let validationReason = '';

  if (proposalType === 'threshold_adjustment') {
    const rule = RULE_TABLE.threshold_adjustment[targetType];
    if (!rule) { validationFailed = true; validationReason = 'Unbekannter config_key: ' + targetType; }
    else { const r = checkRule(rule, proposedValue); if (!r.ok) { validationFailed = true; validationReason = r.reason; } }
  } else if (proposalType === 'strategy_parameter_change') {
    if (!VALID_STRATEGIES.has(targetType)) { validationFailed = true; validationReason = 'Unbekannte Strategie: ' + targetType; }
    else {
      const rule = RULE_TABLE.strategy_parameter_change[targetValue];
      if (!rule) { validationFailed = true; validationReason = 'Unbekannter parameter_key: ' + targetValue; }
      else { const r = checkRule(rule, proposedValue); if (!r.ok) { validationFailed = true; validationReason = r.reason; } }
    }
  } else if (proposalType === 'regime_restriction') {
    if (!VALID_STRATEGIES.has(targetType)) { validationFailed = true; validationReason = 'Unbekannte Strategie: ' + targetType; }
    else if (!VALID_COMBINED_REGIMES.has(targetValue)) { validationFailed = true; validationReason = 'Unbekanntes combined_regime: ' + targetValue; }
    else { const r = checkRule(FIT_MULTIPLIER_RULE, proposedValue); if (!r.ok) { validationFailed = true; validationReason = r.reason; } }
  } else if (proposalType === 'strategy_deactivation') {
    if (!VALID_STRATEGIES.has(targetType)) { validationFailed = true; validationReason = 'Unbekannte Strategie: ' + targetType; }
  } else {
    // weight_adjustment (Default-Zweig) - kein fester Schluessel-Katalog (Quelle x Zeitfenster
    // sind frei kombinierbar, siehe Workflow 09), aber der Wertebereich wird durchgesetzt
    // (identische Grenzen wie die bereits getestete Validierung in Workflow 09, F2-Fix).
    const r = checkRule(WEIGHT_VALUE_RULE, proposedValue);
    if (!r.ok) { validationFailed = true; validationReason = r.reason; }
  }

  if (validationFailed) {
    sql = `UPDATE trading.learning_rule_proposals
      SET status = 'activation_failed', reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1
      WHERE id = ${id} AND status = 'proposed';`;
  } else if (proposalType === 'threshold_adjustment') {
    sql = `BEGIN;
      WITH upd AS (
        UPDATE trading.pipeline_config SET value_numeric = ${proposedValue}, updated_at = now()
          WHERE config_key = ${pgStr(targetType)} AND ${eligible}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else if (proposalType === 'strategy_parameter_change') {
    sql = `BEGIN;
      WITH upd AS (
        UPDATE trading.strategy_parameters SET parameter_value = ${proposedValue}, version = version + 1, source_proposal_id = ${id}, updated_at = now()
          WHERE strategy = ${pgStr(targetType)} AND parameter_key = ${pgStr(targetValue)} AND ${eligible}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else if (proposalType === 'regime_restriction') {
    sql = `BEGIN;
      WITH upd AS (
        UPDATE trading.strategy_regime_matrix
          SET fit_multiplier = ${proposedValue}, blocked = (${proposedValue} <= 0), notes = COALESCE(notes, '') || ' [Welle 3 Lernvorschlag #${id} aktiviert]'
          WHERE rule_version = 'regime-matrix-v1' AND strategy = ${pgStr(targetType)} AND combined_regime = ${pgStr(targetValue)} AND ${eligible}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else if (proposalType === 'strategy_deactivation') {
    sql = `BEGIN;
      WITH upd AS (
        UPDATE trading.strategy_status
          SET aktiv = FALSE, deactivated_at = now(), deactivated_reason = ${pgStr('Lernvorschlag #' + id)}, source_proposal_id = ${id}, updated_at = now()
          WHERE strategy = ${pgStr(targetType)} AND ${eligible}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  } else {
    const weightKey = [targetType, targetValue, timeHorizon].filter(Boolean).join(':');
    sql = `BEGIN;
      WITH deactivated AS (
        UPDATE trading.scoring_weights SET active = FALSE
          WHERE weight_key = ${pgStr(weightKey)} AND active = TRUE AND ${eligible}
          RETURNING 1
      ), inserted AS (
        INSERT INTO trading.scoring_weights
          (weight_key, weight_value, version, active, source_proposal_id, activated_at, activated_by, metadata_json)
        SELECT ${pgStr(weightKey)}, ${proposedValue}, COALESCE(MAX(version), 0) + 1, TRUE, ${id}, now(), ${pgStr(reviewer)}, '{}'::jsonb
          FROM trading.scoring_weights
          WHERE weight_key = ${pgStr(weightKey)} AND ${eligible}
        RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM inserted) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = ${pgStr(reviewer)}, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM inserted) THEN now() ELSE NULL END
        WHERE id = ${id} AND status = 'proposed';
      COMMIT;`;
  }
} else {
  sql = 'SELECT 1;';
}

return [{ json: { sql } }];

// FIX 2026-07-25: n8n-Plattform-Bug entdeckt - wenn eine Postgres-Abfrage 0 Zeilen liefert,
// wird der nachfolgende Node standardmaessig gar nicht ausgefuehrt, was die Webhook-Antwort
// crashen liess (leere Antwort, kein Fehler-Log, kein Execution-Eintrag - nur ueber Server-
// Logs als 'Task rejected by Runner: Offer expired' + interner n8n-TypeError sichtbar).
// Live reproduziert mit einer GARANTIERT leeren Abfrage auf einer bekannt funktionierenden
// Tabelle (trading.watchlist) - also kein Bug in dieser Tabelle/diesem Workflow, sondern ein
// generelles n8n-Verhalten. Fix: alwaysOutputData:true auf dem vorgelagerten Postgres-Node
// erzwingt ein (leeres) Platzhalter-Item, das hier herausgefiltert werden muss.
const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fmtDate(v) {
  if (!v) return '';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function fmtNum(v) {
  return (v === null || v === undefined) ? '' : String(v);
}

const STATUS_LABEL = {
  proposed: 'wartet auf Pruefung',
  approved: 'freigegeben',
  activated: 'aktiviert',
  rejected: 'abgelehnt',
  expired: 'abgelaufen'
};
const STATUS_CLASS = {
  proposed: 'warn',
  approved: 'ok',
  activated: 'ok',
  rejected: 'danger',
  expired: 'muted'
};

const rowsHtml = rows.map(r => {
  const target = esc(r.target_type) + ': ' + esc(r.target_value) + (r.time_horizon ? ' @ ' + esc(r.time_horizon) : '');
  const change = fmtNum(r.current_value) + ' \u2192 <strong>' + fmtNum(r.proposed_value) + '</strong>';
  const metric = r.metric_name ? esc(r.metric_name) + ': ' + fmtNum(r.metric_value) : '';
  const badgeClass = STATUS_CLASS[r.status] || 'muted';
  const badgeLabel = STATUS_LABEL[r.status] || esc(r.status);
  const badge = '<span class="badge ' + badgeClass + '">' + esc(badgeLabel) + '</span>';

  let actionCell;
  if (r.status === 'proposed') {
    const approveId = 'fa-' + r.id;
    const rejectId = 'fr-' + r.id;
    actionCell = '<button form="' + approveId + '" type="submit">Freigeben &amp; aktivieren</button>' +
      '<button class="danger" form="' + rejectId + '" type="submit">Ablehnen</button>' +
      '<form id="' + approveId + '" method="POST" action="/webhook/lernvorschlaege">' +
      '<input type="hidden" name="action" value="approve">' +
      '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
      '<input type="hidden" name="proposal_type" value="' + esc(r.proposal_type) + '">' +
      '<input type="hidden" name="target_type" value="' + esc(r.target_type) + '">' +
      '<input type="hidden" name="target_value" value="' + esc(r.target_value) + '">' +
      '<input type="hidden" name="time_horizon" value="' + esc(r.time_horizon) + '">' +
      '<input type="hidden" name="proposed_value" value="' + esc(r.proposed_value) + '">' +
      // FIX 2026-08-02 (Fehleranalyse A10): version wird jetzt mitgeschickt,
      // damit der Server erkennen kann, ob sich der Vorschlag seit dem Laden
      // dieser Seite bereits geaendert hat (Optimistic Locking) - reines
      // Konkurrenz-Token, kein vertrauenswuerdiger Inhaltswert (die
      // eigentlichen Felder werden weiterhin serverseitig aus der DB
      // nachgeladen, siehe A5).
      '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
      '</form>' +
      '<form id="' + rejectId + '" method="POST" action="/webhook/lernvorschlaege">' +
      '<input type="hidden" name="action" value="reject">' +
      '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
      '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
      '<input type="hidden" name="reviewer" value="">' +
      '</form>';
  } else {
    actionCell = esc(r.reviewed_by || '') + (r.activated_at ? ' \u00b7 ' + fmtDate(r.activated_at) : (r.reviewed_at ? ' \u00b7 ' + fmtDate(r.reviewed_at) : ''));
  }

  return '<tr>' +
    '<td>' + esc(r.id) + '</td>' +
    '<td>' + target + '</td>' +
    '<td>' + change + '</td>' +
    '<td>' + esc(r.sample_size) + '</td>' +
    '<td>' + esc(r.confidence_level) + '<br><span class="hint-inline">' + metric + '</span></td>' +
    '<td class="reason">' + esc(String(r.reason || '').slice(0, 220)) + '</td>' +
    '<td>' + badge + '<br><span class="hint-inline">' + fmtDate(r.created_at) + '</span></td>' +
    '<td>' + actionCell + '</td>' +
    '</tr>';
}).join('\n');

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const pendingCount = rows.filter(r => r.status === 'proposed').length;

const html = '<!DOCTYPE html>' +
